-- Reverses this batch only on an empty database. Existing founder data blocks
-- rollback; use a forward compatibility migration for a populated deployment.
begin;
do $$begin if exists(select from public.missions)or exists(select from public.founders)then raise exception 'Data-preserving rollback blocked: founder data exists; apply a forward migration';end if;end$$;
drop view if exists public.active_decisions,public.current_artifact_versions,public.money_totals;
do $$declare f record;begin for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['propose_decision','resolve_decision','add_dependency','create_artifact','append_artifact_version','set_artifact_status','append_evidence','open_commitment','close_commitment','issue_approval','grant_mandate','revoke_mandate','transition_mission','reserve_effect','begin_effect','complete_effect','fail_effect','prepare_payment','confirm_payment','effect_receipt','revoke_account','readiness','active_blockers','mission_snapshot','create_mission','append_founder_message','append_lead_message','can_join_mission'])loop execute 'drop function '||f.signature||' cascade';end loop;end$$;
do $$begin if to_regclass('realtime.messages')is not null then execute 'drop policy if exists lo_private_mission on realtime.messages';end if;if to_regclass('storage.objects')is not null then execute 'drop policy if exists lo_mission_files_read on storage.objects';execute 'drop policy if exists lo_mission_files_write on storage.objects';end if;end$$;
drop table if exists public.founders,public.missions,public.mission_transitions,public.state_nodes,public.decisions,public.decision_resolutions,public.decision_supersessions,public.dependencies,public.stale_marks,public.artifacts,public.runs,public.artifact_versions,public.artifact_statuses,public.counterparties,public.founder_accounts,public.account_revocations,public.mandates,public.mandate_revocations,public.approvals,public.approval_invalidations,public.effect_authorizations,public.approval_consumptions,public.provider_receipts,public.effect_states,public.evidence,public.commitments,public.commitment_states,public.events,public.event_consumptions,public.outbox,public.outbox_deliveries,public.payments,public.payment_states,public.money_ledger,public.activity,public.threads,public.messages,public.tasks,public.focus_events,public.blockers,public.readiness_rules,public.category_profiles,public.playbooks,public.templates cascade;
drop table if exists private.account_secrets,private.platform_controls;
do $$declare f record;begin for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname=any(array['actor_id','caller_role','require_role','owns_founder','owns_mission','assert_mission','immutable_row','lock_mission','audit','node_before_insert','assert_safe_content','content_guard','invalidate','validate_packet','active_mission','authorization_json','check_version','tenant_reference_guard','broadcast_ledger'])loop execute 'drop function if exists '||f.signature||' cascade';end loop;end$$;
commit;
